<script setup lang="ts">
import { X } from '@lucide/vue'
import UiCheckbox from '../../../components/ui/UiCheckbox.vue'
import UiAlert from '../../../components/ui/UiAlert.vue'
import UiButton from '../../../components/ui/UiButton.vue'
import UiDialog from '../../../components/ui/UiDialog.vue'
import type { Attribute } from '../../attributes/types/attribute.types'
import type { AttributeGroup } from '../../attribute-groups/types/attributeGroup.types'
import type { Category } from '../types/category.types'
import { attributeTypeLabel } from '../../../utils/attributeTypes'
defineProps<{ open: boolean; busy: boolean; error: string; category: Category | null; groups: AttributeGroup[]; groupedAttributes: Array<AttributeGroup & { attributes: Attribute[] }>; ungroupedAttributes: Attribute[]; selectedGroupIds: number[]; selectedAttributeIds: number[]; requiredAttributeIds: number[] }>()
const emit = defineEmits<{ close: []; submit: []; groupsChange: [value: Array<number | string>]; attributesChange: [value: Array<number | string>]; requiredChange: [value: Array<number | string>] }>()
</script>
<template><UiDialog :open="open && Boolean(category)" labelledby="category-attributes-title" describedby="category-attributes-description" :close-disabled="busy" panel-class="w-full max-w-xl" @close="emit('close')"><form v-if="category" class="max-h-[90vh] w-full overflow-y-auto rounded-xl bg-white p-6 shadow-xl" @submit.prevent="emit('submit')"><div class="flex items-start justify-between gap-4"><div><h2 id="category-attributes-title" class="text-lg font-bold text-gray-900">Характеристики: {{ category.name }}</h2><p id="category-attributes-description" class="mt-1 text-sm text-gray-500">Выберите характеристики, доступные для товаров этой категории.</p></div><UiButton type="button" variant="ghost" size="sm" aria-label="Закрыть окно характеристик категории" :disabled="busy" @click="emit('close')"><X :size="20" /></UiButton></div><UiAlert v-if="error" class="mt-4">{{ error }}</UiAlert><div class="mt-6 max-h-80 space-y-4 overflow-y-auto"><section class="rounded-xl border border-gray-200 p-3"><h3 class="mb-2 text-sm font-semibold text-gray-800">Группы характеристик</h3><div class="grid gap-2 sm:grid-cols-2"><UiCheckbox v-for="group in groups" :key="group.id" :model-value="selectedGroupIds" :value="group.id" class="h-auto min-h-[42px]" @update:model-value="emit('groupsChange', $event)">{{ group.name }}</UiCheckbox></div></section><section v-for="group in groupedAttributes" :key="group.id" class="overflow-hidden rounded-xl border border-gray-200"><div class="bg-gray-50 px-4 py-3"><h3 class="font-semibold text-gray-800">{{ group.name }}</h3></div><div v-for="attribute in group.attributes" :key="attribute.id" class="flex flex-wrap items-center gap-2 border-t border-gray-100 px-4 py-3"><UiCheckbox :model-value="selectedAttributeIds" :value="attribute.id" class="h-auto min-h-[42px] flex-1 border-0" @update:model-value="emit('attributesChange', $event)"><span class="font-medium text-gray-800">{{ attribute.name }} <span class="text-xs text-gray-500">/{{ attribute.slug }} · {{ attributeTypeLabel(attribute.type) }}</span></span></UiCheckbox><UiCheckbox v-if="selectedAttributeIds.includes(attribute.id)" :model-value="requiredAttributeIds" :value="attribute.id" class="h-auto min-h-[42px]" :accessible-name="`Обязательная характеристика: ${attribute.name}`" @update:model-value="emit('requiredChange', $event)">Обязательная</UiCheckbox></div><p v-if="!group.attributes.length" class="px-4 py-3 text-sm text-gray-500">В группе пока нет характеристик.</p></section><section v-if="ungroupedAttributes.length" class="overflow-hidden rounded-xl border border-gray-200"><div class="bg-gray-50 px-4 py-3"><h3 class="font-semibold text-gray-800">Без группы</h3></div><div v-for="attribute in ungroupedAttributes" :key="attribute.id" class="flex flex-wrap items-center gap-2 border-t border-gray-100 px-4 py-3"><UiCheckbox :model-value="selectedAttributeIds" :value="attribute.id" class="h-auto min-h-[42px] flex-1 border-0" @update:model-value="emit('attributesChange', $event)">{{ attribute.name }}</UiCheckbox><UiCheckbox v-if="selectedAttributeIds.includes(attribute.id)" :model-value="requiredAttributeIds" :value="attribute.id" class="h-auto min-h-[42px]" @update:model-value="emit('requiredChange', $event)">Обязательная</UiCheckbox></div></section></div><div class="mt-6 flex flex-wrap justify-end gap-3"><UiButton type="button" variant="ghost" :disabled="busy" @click="emit('close')">Отмена</UiButton><UiButton :loading="busy">Сохранить</UiButton></div></form></UiDialog></template>
